import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Эндпоинты","description":"","frontmatter":{},"headers":[],"relativePath":"ru/concepts/endpoints.md","filePath":"ru/concepts/endpoints.md","lastUpdated":1784903584000}'),d={name:"ru/concepts/endpoints.md"};function o(p,a,r,i,c,l){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="эндпоинты" tabindex="-1">Эндпоинты <a class="header-anchor" href="#эндпоинты" aria-label="Permalink to &quot;Эндпоинты&quot;">​</a></h1><p>Эндпоинт — это конкретный HTTP-метод + путь, который можно вызвать (например, <code>GET /api/users/{id}</code>). Эндпоинты — это фактические операции API, которые LLM обнаруживает, изучает и вызывает.</p><h2 id="структура" tabindex="-1">Структура <a class="header-anchor" href="#структура" aria-label="Permalink to &quot;Структура&quot;">​</a></h2><p>Каждый эндпоинт содержит:</p><ul><li><strong>HTTP-метод</strong>: GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS</li><li><strong>Путь</strong>: <code>/api/v1/users/{id}</code></li><li><strong>Summary</strong>: краткое описание того, что делает эндпоинт — очень полезно для LLM, чтобы быстро понять его назначение</li><li><strong>Description</strong>: подробное объяснение поведения эндпоинта, его параметров и вариантов использования</li><li><strong>Параметры</strong>: path, query, header, cookie</li><li><strong>Тело запроса</strong>: для POST/PUT/PATCH</li><li><strong>Ответы</strong>: коды статуса и схемы ответов</li></ul><p>Поля <code>summary</code> и <code>description</code> берутся из файла OpenAPI/Swagger/Postman. Это основной способ, с помощью которого LLM понимает, что делает эндпоинт. Хорошо написанные summary делают поиск эндпоинтов гораздо эффективнее.</p><h2 id="mcp-инструменты-для-эндпоинтов" tabindex="-1">MCP-инструменты для эндпоинтов <a class="header-anchor" href="#mcp-инструменты-для-эндпоинтов" aria-label="Permalink to &quot;MCP-инструменты для эндпоинтов&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Инструмент</th><th>Описание</th></tr></thead><tbody><tr><td><code>endpoint_by_spec</code></td><td>Все эндпоинты в спецификации</td></tr><tr><td><code>endpoint_by_collection</code></td><td>Эндпоинты в коллекции</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Эндпоинты в теге</td></tr><tr><td><code>endpoint_by_id</code></td><td>Краткая сводка эндпоинта</td></tr><tr><td><code>inspect</code></td><td>Полная информация об эндпоинте (схемы, параметры)</td></tr><tr><td><code>invoke</code></td><td>Вызов эндпоинта</td></tr><tr><td><code>search</code></td><td>Поиск эндпоинтов по тексту</td></tr></tbody></table><h2 id="устаревшие-эндпоинты" tabindex="-1">Устаревшие эндпоинты <a class="header-anchor" href="#устаревшие-эндпоинты" aria-label="Permalink to &quot;Устаревшие эндпоинты&quot;">​</a></h2><p>Эндпоинты, помеченные как <code>deprecated</code> в спецификации, отображаются с предупреждением при просмотре.</p><h2 id="конфигурация" tabindex="-1">Конфигурация <a class="header-anchor" href="#конфигурация" aria-label="Permalink to &quot;Конфигурация&quot;">​</a></h2><p>Эндпоинты <strong>доступны только для чтения</strong> с точки зрения swag2mcp. В YAML-конфиге нет настроек для эндпоинтов — вы не можете добавлять, удалять, переименовывать или изменять их в <code>swag2mcp.yaml</code>.</p><p>Чтобы изменить эндпоинты (добавить новые, обновить summary, изменить параметры, пометить как устаревшие), отредактируйте исходный файл OpenAPI/Swagger/Postman и выполните <code>swag2mcp update</code> для повторного разбора и индексации.</p><h2 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Запрос: &quot;Покажи детали GET /pet/{petId}&quot;</span></span>
<span class="line"><span>→ inspect(endpointId: &quot;abc123...&quot;)</span></span>
<span class="line"><span>→ Результат:</span></span>
<span class="line"><span>  GET /pet/{petId}</span></span>
<span class="line"><span>  Summary: Найти питомца по ID</span></span>
<span class="line"><span>  Description: Возвращает одного питомца по его ID</span></span>
<span class="line"><span>  Параметры:</span></span>
<span class="line"><span>    - petId (path, integer, обязательно)</span></span>
<span class="line"><span>  Ответы:</span></span>
<span class="line"><span>    - 200: Объект Pet</span></span>
<span class="line"><span>    - 400: Ошибка</span></span>
<span class="line"><span>    - 404: Не найдено</span></span></code></pre></div>`,15)])])}const m=t(d,[["render",o]]);export{u as __pageData,m as default};
